#!/usr/bin/env bash
# Blind checkpoint — twine-src session twine-seed-close, v1.
# Authored at sitting 2026-09-29-begin-harness-001 from the request alone
# (TARBALL.md 7; PLANNER.md 4). Outcome contracts only; cwd = the staged
# tree, confined, network off. Exit 0 pass; 1 a probe failed; 2 broken.
# Embedded: the seed as it stood at authoring (sha256 cabf7615…) and the
# nine insertion texts the brief ships byte-for-byte. Pins bytes inside
# the forecast (twine-seed.md) only — out-of-forecast paths are bale's
# forecast gate's to guard (this session's own T3 annotation).
# Writes: one private temp directory (mktemp -d), removed on exit.
set -u
export PYTHONDONTWRITEBYTECODE=1
self_error() { echo "[ERROR] checkpoint: $1"; exit 2; }
command -v python3 >/dev/null 2>&1 || self_error "python3 not found on PATH"
TMP="$(mktemp -d 2>/dev/null || true)"
[ -n "$TMP" ] && [ -d "$TMP" ] || { TMP="./.checkpoint-tmp.$$"; mkdir -p "$TMP" || self_error "cannot create a temp dir"; }
trap 'rm -rf "$TMP"' EXIT
echo "checkpoint twine-seed-close v1: temp dir $TMP (removed on exit); tree writes: none"
B64=''
printf '%s' "$B64" | base64 -d | tar -xzf - -C "$TMP" 2>/dev/null || self_error "could not unpack the embedded baseline"
[ "$(sha256sum "$TMP/baseline.md" | cut -d' ' -f1)" = "cabf76158430bdcb84366afc52cbea6c5662e2870e069f8375f69642cd3e164e" ] || self_error "embedded baseline hash mismatch"

cat > "$TMP/probe.py" <<'PYEOF'
import re, sys, pathlib
D = pathlib.Path(sys.argv[1]); target = pathlib.Path(sys.argv[2])
SID = re.compile(r"\[(20\d\d-\d\d-\d\d-twine-seed-close-\d{3}): ")
INS = [  # file, label, start anchor, end anchor (regexes over whole lines; None = EOF)
 ("I1-s2-preamble.md", "the section 2 preamble annotation", r"## 2\. Rulings", r"\*\*T1 — "),
 ("I2a-T3-baletoml.md", "the bale.toml rationale beneath T3", r"\*\*T3 — ", r"\*\*T4 — "),
 ("I2b-T3-pinning.md", "the checkpoint-pinning annotation beneath T3", r"\*\*T3 — ", r"\*\*T4 — "),
 ("I3-T4-shapes.md", "the four-shapes annotation beneath T4", r"\*\*T4 — ", r"\*\*T5 — "),
 ("I4-T12-T14.md", "T12, T13 and T14 after T11", r"\*\*T11 — ", r"## 3\. "),
 ("I5-arc1.md", "the two Arc 1 annotations in 5.1", r"### 5\.1 ", r"### 5\.2 "),
 ("I6-s8-intro.md", "the section 8 intro annotation", r"## 8\. ", r"Message 1 "),
 ("I7-messages.md", "messages 7 to 11 verbatim", r"Message 6 ", r"### How the sitting ended"),
 ("I8-close.md", "the closing annotation", r"### How the sitting ended", None),
]
def out(ok, label): print(("[PASS] " if ok else "[FAIL] ") + label)
base = (D / "baseline.md").read_text(encoding="utf-8").split("\n")
try:
    text = target.read_bytes().decode("utf-8")
except Exception:
    text = None
if text is None:
    out(False, "twine-seed.md is present and UTF-8")
    for f, label, a, b in INS: out(False, label + " landed byte-exact in its place")
    out(False, "insertion-only: every line of the seed as shipped is present in order")
    out(False, "one session id throughout, no <sid> placeholder left, no TODO"); sys.exit(0)
lines = text.split("\n")
i = 0
for l in lines:
    if i < len(base) and l == base[i]: i += 1
out(i == len(base), "insertion-only: every line of the seed as shipped is present in order")
sids = set(SID.findall(text))
norm_lines = [SID.sub("[<sid>: ", l) for l in lines]
def region(a, b):
    s = next((k for k, l in enumerate(norm_lines) if re.match(a, l)), None)
    if s is None: return None
    e = len(norm_lines) if b is None else next((k for k in range(s + 1, len(norm_lines)) if re.match(b, norm_lines[k])), None)
    return None if e is None else "\n".join(norm_lines[s:e])
pos = {}
for f, label, a, b in INS:
    want = (D / f).read_text(encoding="utf-8").rstrip("\n")
    r = region(a, b)
    ok = r is not None and ("\n" + want + "\n") in ("\n" + r + "\n")
    if ok: pos[f] = r.index(want)
    out(ok, label + " landed byte-exact in its place")
if "I2a-T3-baletoml.md" in pos and "I2b-T3-pinning.md" in pos:
    out(pos["I2a-T3-baletoml.md"] < pos["I2b-T3-pinning.md"], "beneath T3, the bale.toml rationale comes before the pinning rule")
else:
    out(False, "beneath T3, the bale.toml rationale comes before the pinning rule")
out(len(sids) == 1 and "[<sid>:" not in text and "TODO" not in text, "one session id throughout, no <sid> placeholder left, no TODO")
PYEOF

# control: the probe must pass insertion-only and fail every insertion on the baseline itself
python3 "$TMP/probe.py" "$TMP" "$TMP/baseline.md" > "$TMP/ctl.out" 2>&1 || self_error "control: probe crashed on the baseline"
grep -q "^\[PASS\] insertion-only" "$TMP/ctl.out" || self_error "control: insertion-only rejected the baseline"
[ "$(grep -c '^\[FAIL\] .* landed byte-exact in its place' "$TMP/ctl.out")" = "9" ] || self_error "control: an insertion probe passed on the baseline"
echo "[control] detectors verified against the baseline"

python3 "$TMP/probe.py" "$TMP" twine-seed.md > "$TMP/probe.out" 2>&1 || self_error "probe crashed: $(head -c 300 "$TMP/probe.out")"
cat "$TMP/probe.out"
fails=$(grep -c '^\[FAIL\]' "$TMP/probe.out" || true)
echo "checkpoint twine-seed-close v1: $fails probe(s) failed"
[ "$fails" -eq 0 ] && exit 0 || exit 1
